import React from 'react'

let taskList = [{ id: 1, itemName: 'Laptop', qty: 1 }, { id: 2, itemName: 'Notebook', qty: 2 }, { id: 3, itemName: 'Pen', qty: 1 }];
const TodoList = () => {
    return (
        <div>
            <Form />
        </div>
    )
}

export default TodoList;

function Form() {
    return (
        <div>
            <form className='container mt-5 p-3 border border-2 rounded bg-warning-subtle'>
                <section className="mb-3">
                    <h2 className="form-label  text-center "><span className='badge badge-success m-2'>Required Items to bring!</span></h2>

                    <input type="text" className="form-control" placeholder='Enter Items 📍' />
                </section>
                <input type='submit' className="btn btn-sm btn-amber text-dark" />
                <TaskList/>
            </form>
        </div>
    );
}


function TaskList() {
    return (
        <>
            <ul className='list-group mt-3'>
                {taskList.map((item) => <Task item={item}/>)}
            </ul>
        </>
    );
}

function Task({ item }) {
    let { itemName, qty } = item;
    return (
        <li className='list-group-item d-flex justify-content-between align-items-center'>
            <span className='text-monospace fs-5'>{itemName}<span className='badge badge-primary badge-pill'>{qty}</span></span>
            
            <button className='btn btn-danger btn-sm'>Delete</button>
        </li>
    );
}
